package com.vpt.scout.ui

import java.net.URLEncoder
import java.util.Locale

/** Matches the address links generated by scan/populate_search_urls.py. */
internal fun cyberBackgroundChecksUrl(address: String?, city: String?, zipCode: String?): String? {
    val locality = city?.trim()?.takeIf { it.isNotEmpty() } ?: return null
    val rawAddress = address?.trim()?.takeIf { it.isNotEmpty() && !it.equals("Unknown", true) }
        ?: return null
    val zip = Regex("\\b\\d{5}(?:-\\d{4})?\\b")
        .find(zipCode.orEmpty())?.value?.take(5)
        ?: Regex("\\b\\d{5}(?:-\\d{4})?$").find(rawAddress)?.value?.take(5)
        ?: return null
    val citySuffix = Regex(
        "\\s+${Regex.escape(locality)}(?:\\s+CA)?(?:\\s+\\d{5}(?:-\\d{4})?)?$",
        RegexOption.IGNORE_CASE
    )
    val street = rawAddress.substringBefore(',').replace(citySuffix, "").trim()
    if (street.isEmpty()) return null
    fun slug(value: String) = URLEncoder.encode(
        value.lowercase(Locale.ROOT).replace(Regex("\\s+"), "-"), "UTF-8"
    ).replace("+", "%20")
    return "https://www.cyberbackgroundchecks.com/address/${slug(street)}/${slug(locality)}/$zip"
}
